package cn.course.community;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.password.PasswordEncoder;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:account-settings;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class AccountSettingsTest {
 static final String OLD="TestOnly!2026Long",NEW="ChangedOnly!2026Long";
 @Autowired MockMvc mvc;@Autowired Store s;@Autowired AccountService accounts;@Autowired PasswordEncoder encoder;
 String email="student@example.test";
 MockHttpSession login(String password)throws Exception{return (MockHttpSession)mvc.perform(post("/api/auth/login").param("username",email).param("password",password).with(csrf())).andExpect(status().isOk()).andReturn().getRequest().getSession(false);}
 AccountService.PasswordResult change(String old,String next,String confirmation){return accounts.changePassword(email,0,old,next,confirmation);}
 String body(String current,String next,String confirm){return sjson(Map.of("currentPassword",current,"newPassword",next,"confirmation",confirm));}
 String sjson(Object o){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(o);}catch(Exception e){throw new RuntimeException(e);}}
 @Test void personalProfileContainsOnlySafeFields()throws Exception{mvc.perform(get("/api/account").session(login(OLD))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("email").value(email)).andExpect(jsonPath("password_hash").doesNotExist()).andExpect(jsonPath("credential_version").doesNotExist()).andExpect(jsonPath("password_failures").doesNotExist());assertEquals(Set.of("id","email","display_name","is_teacher","profile_revision","password_changed_at"),accounts.profile(email).keySet());}
 @Test void anonymousAndMissingCsrfAreRejected()throws Exception{mvc.perform(get("/api/account")).andExpect(status().isUnauthorized());mvc.perform(put("/api/account/profile").session(login(OLD)).contentType("application/json").content("{\"displayName\":\"changed\",\"revision\":0}")).andExpect(status().isForbidden());mvc.perform(put("/api/account/password").session(login(OLD)).contentType("application/json").content(body(OLD,NEW,NEW))).andExpect(status().isForbidden());}
 @Test void nameChangesAreScopedAndTrimmed()throws Exception{String peer=(String)accounts.profile("peer@example.test").get("display_name");mvc.perform(put("/api/account/profile").session(login(OLD)).with(csrf()).contentType("application/json").content("{\"displayName\":\"  新名称  \",\"revision\":0}")).andExpect(status().isOk()).andExpect(jsonPath("display_name").value("新名称")).andExpect(jsonPath("email").value(email)).andExpect(jsonPath("profile_revision").value(1));assertEquals(peer,accounts.profile("peer@example.test").get("display_name"));assertEquals("STUDENT",s.role(1,s.uid(email)));}
 @Test void nameConflictPreservesLatestValue(){accounts.updateName(email,"第一窗口",0L);var e=assertThrows(ApiError.Failure.class,()->accounts.updateName(email,"旧窗口",0L));assertEquals(409,e.status);assertEquals("第一窗口",accounts.profile(email).get("display_name"));}
 @Test void nameValidationCoversEmptyLongAndControls(){for(String value:List.of(" ","x".repeat(41),"名称\n换行","隐藏\u200b字符")){var e=assertThrows(ApiError.Failure.class,()->accounts.updateName(email,value,0L));assertEquals(400,e.status);}assertThrows(ApiError.Failure.class,()->accounts.updateName(email,null,0L));assertThrows(ApiError.Failure.class,()->accounts.updateName(email,"名称",null));}
 @Test void unicodeNameAndNoOpAreSupported(){String name="🌱".repeat(40);assertEquals(name,accounts.updateName(email,name,0L).get("display_name"));assertEquals(1L,((Number)accounts.updateName(email,name,1L).get("profile_revision")).longValue());}
 @Test void passwordPolicyRejectsShortMismatchAndSame(){assertEquals(400,change(OLD,"short","short").status());assertEquals(400,change(OLD," ".repeat(12)," ".repeat(12)).status());assertEquals(400,change(OLD,NEW,NEW+"x").status());assertEquals(400,change(OLD,OLD,OLD).status());assertEquals(400,change(OLD,"a".repeat(73),"a".repeat(73)).status());assertEquals(400,change(OLD,"line\nbreak".repeat(2),"line\nbreak".repeat(2)).status());assertEquals(0L,((Number)s.one("SELECT credential_version FROM app_user WHERE email=?",email).get("credential_version")).longValue());}
 @Test void utf8LimitNotJustCharacterCount(){String tooLong="中".repeat(25);assertEquals(400,change(OLD,tooLong,tooLong).status());String exact="中".repeat(24);assertEquals(200,change(OLD,exact,exact).status());assertTrue(encoder.matches(exact,(String)s.one("SELECT password_hash FROM app_user WHERE email=?",email).get("password_hash")));}
 @Test void wrongCurrentDoesNotChangePassword(){assertEquals(400,change("incorrect-current",NEW,NEW).status());assertTrue(encoder.matches(OLD,(String)s.one("SELECT password_hash FROM app_user WHERE email=?",email).get("password_hash")));assertEquals(1,((Number)s.one("SELECT password_failures FROM app_user WHERE email=?",email).get("password_failures")).intValue());}
 @Test void failedAttemptsAreDurableAndLocked(){for(int i=1;i<=5;i++)assertEquals(i==5?429:400,change("wrong",NEW,NEW).status());assertEquals(429,change(OLD,NEW,NEW).status());assertEquals(0L,((Number)s.one("SELECT credential_version FROM app_user WHERE email=?",email).get("credential_version")).longValue());}
 @Test void expiredLockAllowsValidChange(){s.db.update("UPDATE app_user SET password_failures=5,password_locked_until='2000-01-01T00:00:00Z' WHERE email=?",email);assertEquals(200,change(OLD,NEW,NEW).status());assertEquals(0,((Number)s.one("SELECT password_failures FROM app_user WHERE email=?",email).get("password_failures")).intValue());}
 @Test void passwordChangeInvalidatesAllOldSessionsNotOtherAccounts()throws Exception{var first=login(OLD);var second=login(OLD);var peer=(MockHttpSession)mvc.perform(post("/api/auth/login").param("username","peer@example.test").param("password",OLD).with(csrf())).andExpect(status().isOk()).andReturn().getRequest().getSession(false);mvc.perform(put("/api/account/password").session(first).with(csrf()).contentType("application/json").content(body(OLD,NEW,NEW))).andExpect(status().isOk());assertTrue(first.isInvalid());mvc.perform(get("/api/auth/me").session(second)).andExpect(status().isUnauthorized());assertTrue(second.isInvalid());mvc.perform(get("/api/auth/me").session(peer)).andExpect(status().isOk()).andExpect(jsonPath("email").value("peer@example.test"));mvc.perform(post("/api/auth/login").param("username",email).param("password",OLD).with(csrf())).andExpect(status().isUnauthorized());mvc.perform(get("/api/auth/me").session(login(NEW))).andExpect(status().isOk());}
 @Test void staleAuthenticatedVersionCannotOverwriteNewPassword(){assertEquals(200,change(OLD,NEW,NEW).status());assertEquals(401,change(NEW,"OtherNew!2026Long","OtherNew!2026Long").status());assertTrue(encoder.matches(NEW,(String)s.one("SELECT password_hash FROM app_user WHERE email=?",email).get("password_hash")));}
 @Test void oldSessionCannotWriteAfterPasswordChange()throws Exception{var session=login(OLD);assertEquals(200,change(OLD,NEW,NEW).status());mvc.perform(put("/api/account/profile").session(session).with(csrf()).contentType("application/json").content("{\"displayName\":\"不应保存\",\"revision\":0}")).andExpect(status().isUnauthorized());assertEquals("林同学",accounts.profile(email).get("display_name"));}
 @Test void passwordChangePreservesDraftsSubmissionsAndCourseRole(){var entry=s.one("SELECT draft_json,evidence_json,revision FROM entry WHERE id=1");int submissions=s.db.queryForObject("SELECT COUNT(*) FROM submission",Integer.class);assertEquals(200,change(OLD,NEW,NEW).status());assertEquals(entry,s.one("SELECT draft_json,evidence_json,revision FROM entry WHERE id=1"));assertEquals(submissions,s.db.queryForObject("SELECT COUNT(*) FROM submission",Integer.class));assertEquals("STUDENT",s.role(1,s.uid(email)));assertNotNull(accounts.profile(email).get("password_changed_at"));}
 @Test void auditOnlyRecordsActionAndAccountId(){accounts.updateName(email,"新名称",0L);assertEquals(200,change(OLD,NEW,NEW).status());var audit=s.db.queryForList("SELECT * FROM audit_log WHERE resource_type='account'");assertEquals(2,audit.size());assertFalse(audit.toString().contains(OLD));assertFalse(audit.toString().contains(NEW));assertFalse(audit.toString().contains("新名称"));}
 @Test void rateLimitHeaderAndCounterSurviveApiFailure()throws Exception{var session=login(OLD);for(int i=1;i<=5;i++){var result=mvc.perform(put("/api/account/password").session(session).with(csrf()).contentType("application/json").content(body("wrong",NEW,NEW)));if(i==5)result.andExpect(status().isTooManyRequests()).andExpect(header().string("Retry-After","900"));else result.andExpect(status().isBadRequest());}assertEquals(5,((Number)s.one("SELECT password_failures FROM app_user WHERE email=?",email).get("password_failures")).intValue());}
 @Test void profileChangeDoesNotInvalidateLogin()throws Exception{var session=login(OLD);accounts.updateName(email,"新名称",0L);mvc.perform(get("/api/auth/me").session(session)).andExpect(status().isOk()).andExpect(jsonPath("display_name").value("新名称"));}
 @Test void identityAndRoleOverpostingIsRejected()throws Exception{mvc.perform(put("/api/account/profile").session(login(OLD)).with(csrf()).contentType("application/json").content("{\"displayName\":\"非法目标\",\"revision\":0,\"email\":\"peer@example.test\",\"role\":\"TEACHER\"}")).andExpect(status().isBadRequest());assertEquals("林同学",accounts.profile(email).get("display_name"));assertEquals("STUDENT",s.role(1,s.uid(email)));}
}
